def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    phases = {}
    for r, row in enumerate(grid):
        for c, v in enumerate(row):
            if v:
                counts[v] = counts.get(v, 0) + 1
                phases.setdefault(v, set()).add((c - r) % 3)

    # The color forming a single diagonal modulo 3 is the repeating
    # one-cell stripe; the other color fills the remaining two stripes.
    stripe = next((v for v in counts if len(phases[v]) == 1), next(iter(counts)))
    phase = next(iter(phases[stripe]))
    other = next(v for v in counts if v != stripe)
    return [[stripe if (c - r) % 3 == phase else other
             for c in range(w)] for r in range(h)]
